package com.mealflex.seller.controller;
import com.mealflex.security.UserPrincipal; import com.mealflex.seller.dto.StoreStaffResponse; import com.mealflex.seller.service.StoreStaffService; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/staff/invitations") @RequiredArgsConstructor public class StoreStaffInvitationController { private final StoreStaffService service; @PostMapping("/accept") public ResponseEntity<StoreStaffResponse> accept(@AuthenticationPrincipal UserPrincipal p,@RequestBody AcceptRequest request){return ResponseEntity.ok(service.accept(p.getId(),request.token()));} public record AcceptRequest(String token){} }
